import fs from 'node:fs';

const records = JSON.parse(
  fs.readFileSync(new URL('./records.json', import.meta.url), 'utf8')
);

const ALLOWED = new Set(['limit', 'cursor']);
const CURSOR_RE = /^c(0|[1-9]\d*)$/;

export async function listTools() {
  return [
    {
      name: 'audit_page',
      description:
        'Return a page of audit records with an opaque cursor for the next page.',
      inputSchema: {
        type: 'object',
        properties: {
          limit: { type: 'integer', minimum: 1, maximum: 3 },
          cursor: { type: 'string' }
        },
        required: ['limit'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'audit_page') {
    throw new Error('unknown tool');
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('invalid arguments');
  }

  for (const key of Object.keys(args)) {
    if (!ALLOWED.has(key)) {
      throw new Error('unexpected field: ' + key);
    }
  }

  if (
    typeof args.limit !== 'number' ||
    !Number.isInteger(args.limit) ||
    args.limit < 1 ||
    args.limit > 3
  ) {
    throw new Error('invalid limit');
  }
  const limit = args.limit;

  // No cursor -> first page (page 0). Cursor "cN" -> fetch page N+1.
  let page = 0;
  if (args.cursor !== undefined) {
    if (typeof args.cursor !== 'string') {
      throw new Error('malformed cursor');
    }
    const m = CURSOR_RE.exec(args.cursor);
    if (!m) {
      throw new Error('malformed cursor');
    }
    page = Number(m[1]) + 1;
  }

  const offset = page * limit;
  if (offset < 0 || offset >= records.length) {
    throw new Error('unknown cursor');
  }

  const slice = records.slice(offset, offset + limit);
  const nextOffset = offset + limit;
  const next_cursor =
    nextOffset < records.length ? `c${page}` : null;

  return {
    content: [
      { type: 'text', text: JSON.stringify({ records: slice, next_cursor }) }
    ]
  };
}

