{"command": "node -e '
import { callTool } from "./server.mjs";

async function page(args){
  const r = JSON.parse((await callTool("audit_page", args)).content[0].text);
  return r;
}

// Page 1: limit 2, no cursor
let p = await page({limit:2});
console.log("p1", JSON.stringify(p));
// Page 2: cursor c0, limit 2
p = await page({limit:2, cursor:"c0"});
console.log("p2", JSON.stringify(p));
// Page 3: should be empty? offset = 4 = length -> unknown cursor
try { await page({limit:2, cursor:"c1"}); console.log("c1 did NOT throw"); }
catch(e){ console.log("c1 threw:", e.message); }

// limit 1 walk
p = await page({limit:1});
console.log("l1-p1", JSON.stringify(p));
p = await page({limit:1, cursor:"c0"});
console.log("l1-p2", JSON.stringify(p));

// error cases
for (const args of [
  {limit:0}, {limit:4}, {limit:1.5}, {limit:"1"}, {},
  {limit:1, cursor:"x"}, {limit:1, cursor:"c01"}, {limit:1, cursor:"c-1"},
  {limit:1, cursor:1}, {limit:1, extra:"x"}, {limit:1, cursor:"c9"}
]) {
  try { await callTool("audit_page", args); console.log("NO throw for", JSON.stringify(args)); }
  catch(e){ console.log("throws for", JSON.stringify(args), "->", e.message); }
}
try { await callTool("nope", {limit:1}); }
catch(e){ console.log("unknown tool ->", e.message); }
'
"}

